g2:evaluate.expression:
var gr = new GlideRecord('sys_app_application');
gr.addQuery('active', true);
gr.addQuery('title', '!=', 'System Maintenance');
gr.orderBy('title');
gr.orderBy('device_type');
gr.query();

var deviceType = '';
var dt = gr.device_type;
if (dt != 'browser' ${AND} dt != '')
    deviceType = '(' + dt + ')';
deviceType;
